--keel:notx
-- Rollup stop_service_customer_daily of stops, generated by keel's analytics/rollup. Do not edit; change the declaration and generate again.
CREATE TABLE IF NOT EXISTS keel_rollup_dirty (
    rollup text COLLATE "C" NOT NULL,
    tenant_key text COLLATE "C" NOT NULL,
    bucket timestamptz NOT NULL,
    xid xid8 NOT NULL,
    marked_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (rollup, tenant_key, bucket, xid)
);
CREATE INDEX IF NOT EXISTS keel_rollup_dirty_marked ON keel_rollup_dirty (marked_at);
CREATE TABLE IF NOT EXISTS keel_rollup_state (
    rollup text COLLATE "C" PRIMARY KEY,
    ready_at timestamptz NOT NULL
);
DELETE FROM keel_rollup_state WHERE rollup = 'stop_service_customer_daily';
DELETE FROM keel_rollup_dirty WHERE rollup = 'stop_service_customer_daily';
DO $keel$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_class WHERE oid = to_regclass('"stop_service_customer_daily"') AND obj_description(oid, 'pg_class') = 'keel rollup stop_service_customer_daily of stops') THEN
        DROP TABLE "stop_service_customer_daily";
    END IF;
END
$keel$;
CREATE TABLE "stop_service_customer_daily" AS SELECT s."business_unit_id" AS "business_unit_id", s."organization_id" AS "organization_id", date_trunc('day', to_timestamp(s."actual_arrival"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = s."organization_id"), 'UTC'))) AS "bucket", s."customer_id" AS "customer_id", count(*) AS "row_count", count(*) FILTER (WHERE s."actual_arrival" <= coalesce(s."scheduled_window_end", s."scheduled_window_start")) AS "on_time_stops", count(*) FILTER (WHERE NOT (s."actual_arrival" <= coalesce(s."scheduled_window_end", s."scheduled_window_start"))) AS "late_stops" FROM "stops" s GROUP BY 1, 2, 3, 4 WITH NO DATA;
COMMENT ON TABLE "stop_service_customer_daily" IS 'keel rollup stop_service_customer_daily of stops';
ALTER TABLE "stop_service_customer_daily" ALTER COLUMN "business_unit_id" SET NOT NULL, ALTER COLUMN "organization_id" SET NOT NULL;
CREATE UNIQUE INDEX "stop_service_customer_daily_key" ON "stop_service_customer_daily" ("business_unit_id", "organization_id", "bucket", "customer_id") NULLS NOT DISTINCT;
CREATE OR REPLACE FUNCTION keel_rollup_stop_service_customer_daily() RETURNS trigger LANGUAGE plpgsql AS $keel$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid)
        SELECT DISTINCT 'stop_service_customer_daily', replace(replace(coalesce(n."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(n."organization_id"::text, ''), '\', '\\'), '/', '\/'), coalesce(date_trunc('day', to_timestamp(n."actual_arrival"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = n."organization_id"), 'UTC'))), 'infinity'), pg_current_xact_id()
          FROM keel_new n
        ON CONFLICT DO NOTHING;
    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid)
        SELECT DISTINCT 'stop_service_customer_daily', replace(replace(coalesce(n."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(n."organization_id"::text, ''), '\', '\\'), '/', '\/'), coalesce(date_trunc('day', to_timestamp(n."actual_arrival"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = n."organization_id"), 'UTC'))), 'infinity'), pg_current_xact_id()
          FROM keel_old n
        ON CONFLICT DO NOTHING;
    ELSE
        INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid)
        SELECT DISTINCT 'stop_service_customer_daily', replace(replace(coalesce(n."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(n."organization_id"::text, ''), '\', '\\'), '/', '\/'), coalesce(date_trunc('day', to_timestamp(n."actual_arrival"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = n."organization_id"), 'UTC'))), 'infinity'), pg_current_xact_id()
          FROM ((SELECT "business_unit_id", "organization_id", "customer_id", "status", "type", "scheduled_window_start", "scheduled_window_end", "actual_arrival" FROM keel_old EXCEPT ALL SELECT "business_unit_id", "organization_id", "customer_id", "status", "type", "scheduled_window_start", "scheduled_window_end", "actual_arrival" FROM keel_new) UNION ALL (SELECT "business_unit_id", "organization_id", "customer_id", "status", "type", "scheduled_window_start", "scheduled_window_end", "actual_arrival" FROM keel_new EXCEPT ALL SELECT "business_unit_id", "organization_id", "customer_id", "status", "type", "scheduled_window_start", "scheduled_window_end", "actual_arrival" FROM keel_old)) n
        ON CONFLICT DO NOTHING;
    END IF;
    RETURN NULL;
END
$keel$;
CREATE OR REPLACE TRIGGER "keel_rollup_stop_service_customer_daily_insert" AFTER INSERT ON "stops" REFERENCING NEW TABLE AS keel_new FOR EACH STATEMENT EXECUTE FUNCTION keel_rollup_stop_service_customer_daily();
CREATE OR REPLACE TRIGGER "keel_rollup_stop_service_customer_daily_update" AFTER UPDATE ON "stops" REFERENCING OLD TABLE AS keel_old NEW TABLE AS keel_new FOR EACH STATEMENT EXECUTE FUNCTION keel_rollup_stop_service_customer_daily();
CREATE OR REPLACE TRIGGER "keel_rollup_stop_service_customer_daily_delete" AFTER DELETE ON "stops" REFERENCING OLD TABLE AS keel_old FOR EACH STATEMENT EXECUTE FUNCTION keel_rollup_stop_service_customer_daily();
--keel:split
WITH marked AS (INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid) SELECT DISTINCT 'stop_service_customer_daily', replace(replace(coalesce(s."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(s."organization_id"::text, ''), '\', '\\'), '/', '\/'), '-infinity'::timestamptz, pg_current_xact_id() FROM "stops" s ON CONFLICT DO NOTHING)
INSERT INTO keel_rollup_state (rollup, ready_at) VALUES ('stop_service_customer_daily', now()) ON CONFLICT (rollup) DO UPDATE SET ready_at = excluded.ready_at;
